theorem acceleration_lower {a0 J S T : ℝ} {a j s : ℝ → ℝ}
    (h : IsAdmissible a0 J S T a j s) {t : ℝ} (ht : t ∈ Icc 0 T) :
    leastAccel a0 J S t ≤ a t
